// Klasa abstrakte
abstract class Animal {
  public abstract void animalSound();
  public void sleep() {
    Console.WriteLine("Zzz");
  }
}

// Klasa e rrjedhur duhet të zbatojë metodën abstrakte
class Pig : Animal {
  public override void animalSound() {
    Console.WriteLine("Derri thotë: wee wee");
  }
}
